from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]; ids={}
for r in range(R):
 for c in range(C):
  if grid[r][c] and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<R and 0<=b<C and grid[a][b] and (a,b) not in seen:
      seen.add((a,b)); q.append((a,b))
   ci=len(comps); comps.append(comp)
   for p in comp: ids[p]=ci
for i,comp in enumerate(comps):
 marks=sorted({grid[r][c] for r,c in comp if grid[r][c]>1})
 if marks: print(i, len(comp), marks, (min(r for r,c in comp),max(r for r,c in comp),min(c for r,c in comp),max(c for r,c in comp)))
out=[row[:] for row in grid]
for r in range(1,R-1):
 for c in range(1,C-1):
  if all(grid[a][b] for a in range(r-1,r+2) for b in range(c-1,c+2)):
   comp=ids[(r,c)]
   markers={grid[x][y] for x,y in comps[comp] if grid[x][y]>1}
   if markers:
    assert len(markers)==1, (r,c,markers)
    out[r][c]=next(iter(markers))
print('\n'.join(' '.join(map(str,row)) for row in out))
